// ── Layout Thrashing: the BAD pattern ────────────────────────
// Each loop iteration: write → dirty layout → read → FORCED SYNC LAYOUT
// Result: N forced layout calculations for N elements
function badResize(elements) {
  elements.forEach(el => {
    const width = el.offsetWidth;          // READ: forces layout flush!
    el.style.width = (width * 1.5) + 'px'; // WRITE: invalidates layout
    // Next iteration: read after write → another forced layout
  });
}

// ── Batched Reads Then Writes: the GOOD pattern ───────────────
// Phase 1: all reads happen before any write → only 1 layout needed
function goodResize(elements) {
  const widths = elements.map(el => el.offsetWidth); // all reads first
  elements.forEach((el, i) => {
    el.style.width = (widths[i] * 1.5) + 'px';       // all writes after
  });
  // Browser defers the single layout until next frame
}

// ── requestAnimationFrame: sync with the render loop ─────────
// rAF fires just before the browser paints the next frame
// Ensures your DOM writes are included in the next frame
// and your DOM reads see a fresh layout from the previous frame
function animateBox(el, targetX) {
  const startX = el.getBoundingClientRect().left; // read BEFORE rAF
  const startTime = performance.now();
  const duration = 400;

  function tick(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    // ease-out cubic: decelerates near the end
    const eased = 1 - Math.pow(1 - progress, 3);
    const dx = (targetX - startX) * eased;

    // transform: compositor-only, no layout or paint triggered
    el.style.transform = `translateX(${dx}px)`;

    if (progress < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// ── Promoting an element before animation starts ──────────────
function animateWithPromotion(el, targetX) {
  // Hint to browser: pre-promote to compositor layer
  el.style.willChange = 'transform';

  animateBox(el, targetX);

  // Clean up after animation: release GPU memory
  el.addEventListener('transitionend', () => {
    el.style.willChange = 'auto';
  }, { once: true });
}

