// ── Detecting layout-triggering property reads ────────────────
// These DOM reads force synchronous layout if layout is pending:
const LAYOUT_TRIGGERS = [
  'offsetTop', 'offsetLeft', 'offsetWidth', 'offsetHeight',
  'offsetParent',
  'scrollTop', 'scrollLeft', 'scrollWidth', 'scrollHeight',
  'clientTop', 'clientLeft', 'clientWidth', 'clientHeight',
  // Methods:
  // getBoundingClientRect(), getClientRects()
  // getComputedStyle() — reads ALL computed styles
  // focus(), select(), scrollIntoView() — also trigger layout
];

// ── CSS properties by pipeline stage cost ────────────────────
const pipelineCost = {
  // Triggers Layout + Paint + Composite:
  layout: [
    'width', 'height', 'padding', 'margin', 'border-width',
    'top', 'left', 'right', 'bottom',
    'font-size', 'font-family', 'font-weight', 'line-height',
    'display', 'position', 'flex-direction', 'grid-template-columns',
    'float', 'clear', 'overflow'
  ],
  // Triggers Paint + Composite only:
  paint: [
    'color', 'background-color', 'border-color',
    'box-shadow', 'text-shadow', 'outline',
    'visibility', 'background-image', 'border-style'
  ],
  // Compositor only — runs on GPU thread:
  composite: [
    'transform',  // translate, scale, rotate, skew
    'opacity',
    'filter',     // only when on promoted layer
    'backdrop-filter'
  ]
};

// ── ResizeObserver: respond to size changes without polling ───
const ro = new ResizeObserver(entries => {
  for (const entry of entries) {
    const { width, height } = entry.contentRect;
    // This callback is called AFTER layout — safe to read sizes here
    // Writing here defers to next frame, no FSL risk
    console.log(`Resized: ${width.toFixed(0)}x${height.toFixed(0)}`);
  }
});
