// ── Long task detection with PerformanceObserver ──────────────
const perfObs = new PerformanceObserver(list => {
  for (const entry of list.getEntries()) {
    console.warn(
      `Long task: ${entry.duration.toFixed(1)}ms at ${entry.startTime.toFixed(0)}ms`,
      entry
    );
  }
});
perfObs.observe({ type: 'longtask', buffered: true });

// ── Intersection Observer: visibility without layout reads ────
const io = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.1 });
